  $$('[data-z]', c).forEach(b => b.onclick = () => { D.sel = b.dataset.z; const z = ZONES.find(x => x.id === D.sel); $('#zp', c).innerHTML = zoneCard(z); DMV.flyTo(z.at, VENUE.id === 'bdf' ? .5 : .8); });
